/**
 * Wire-shape types for antman's search-table endpoints.
 *
 * Mirrors antman's OpenAPI schemas under `/v1/aspects/{aspectId}/...`
 * (the OpenAPI surface itself drops the `/v1` context path, but the
 * deployed routes only respond on the prefixed form — see the client
 * module for details):
 *   - AspectSearchTableSnowflakeCreateRequest (POST /v1/aspects/{aspectId}/search-tables)
 *   - AspectLinkedSearchTableCreateRequest    (POST /v1/aspects/{aspectId}/linked-search-tables)
 *   - AspectSearchTableUpdateInput            (PUT  /v1/aspects/{aspectId}/search-tables/{id})
 *   - SearchTable                             (GET  /v1/aspects/{aspectId}/search-tables/{id}, and every response)
 *   - VectorIndexInput                        (nested)
 *
 * The aspect id moved from the request body to the URL path — both
 * create requests and the update request now identify the owning
 * aspect through the path parameter, not a `aspectId` body field. The
 * shapes here are the literal JSON payload; the serializer in
 * `src/searchTables/serializer/` is the single place that resolves EDK
 * refs (App, AppField, AiProviderConnector, CloudLink) to the id-strings
 * these requests expect.
 */
import type { DeployResponse } from "../../../types.js";
/** Refresh-cadence time unit for snowflake-managed search tables. */
export type SearchTableTimeUnit = "SECONDS" | "MINUTES" | "HOURS" | "DAYS";
/** One vector-index column on a snowflake-managed search table. */
export interface VectorIndexInput {
    readonly fieldId: string;
    readonly aiProviderConnectorId: string;
}
/** Body for `POST /v1/aspects/{aspectId}/search-tables`. Aspect id lives in the URL. */
export interface AspectSearchTableSnowflakeCreateRequest {
    readonly attributeFieldIds: readonly string[];
    readonly duration: SearchTableTimeUnit;
    readonly targetLag: number;
    readonly textIndexFieldIds?: readonly string[];
    readonly warehouse?: string;
    readonly vectorIndexes?: readonly VectorIndexInput[];
    /** Legacy single-index key field; prefer `vectorIndexes`. */
    readonly fieldId?: string;
    /** Legacy single-index embedding provider; prefer per-`vectorIndexes` connector. */
    readonly aiProviderConnectorId?: string;
}
/** Body for `POST /v1/aspects/{aspectId}/linked-search-tables`. Aspect id lives in the URL. */
export interface AspectLinkedSearchTableCreateRequest {
    readonly cloudLinkId: string;
    readonly database: string;
    readonly schema: string;
    readonly serviceName: string;
    readonly warehouse?: string;
}
/** Inner block of the update body — snowflake-only fields today. */
export interface AspectSearchTableSnowflakeUpdateInput {
    readonly duration?: SearchTableTimeUnit;
    readonly targetLag?: number;
    readonly warehouse?: string;
}
/** Body for `PUT /v1/aspects/{aspectId}/search-tables/{id}`. */
export interface AspectSearchTableUpdateInput {
    readonly snowflake?: AspectSearchTableSnowflakeUpdateInput;
}
/** One column on a search table's response payload. */
export interface SearchTableFieldWire {
    readonly id: string;
    readonly name?: string;
    /** Aspect-field variant typename (e.g. `AspectTextField`). */
    readonly type?: string;
}
/**
 * Reference to an AI provider connector on a search-table response.
 * The wire `AiProviderConnectorRef` carries only `id` today; the EDK's
 * authored `AiProviderConnector` ref shape is structurally compatible,
 * so the pulled source can emit a bare `{ id }` literal that satisfies
 * the typed `connector:` slot.
 */
export interface AiProviderConnectorRefWire {
    readonly id: string;
}
/**
 * Vector-index entry on a search-table response payload. Carries both
 * the indexed field and the embedding-provider connector (added on
 * the response side so pulled tables can fully round-trip the create
 * shape).
 */
export interface VectorIndexWire {
    readonly field?: SearchTableFieldWire;
    readonly aiProviderConnector?: AiProviderConnectorRefWire;
}
/**
 * Shared response shape returned by all four search-table endpoints
 * (snowflake create, linked create, thin update, single-get).
 * `__typename` discriminates the variant.
 *
 * Snowflake-specific fields (`field`, `attributeFields`, `textIndexFields`,
 * `vectorIndexes`, `duration`, `targetLag`, `warehouse`, top-level
 * `aiProviderConnector` for the legacy single-index variant) populate
 * for snowflake-managed tables. The `linked*` slots populate for tables
 * pointing at an upstream Cortex Search Service; the cloud-link id
 * isn't exposed on the response yet, so the deserializer prints a
 * `cloudLink: TODO_CLOUD_LINK` placeholder and records a structured
 * miss until the wire grows that field.
 */
export interface SearchTableWire {
    readonly id: string;
    readonly __typename?: "AspectSearchSnowflakeTable" | "AspectLinkedSearchTable" | string;
    /** Server-assigned stable handle (e.g. `"STBL_l0edfxbi"`) — present on the wire despite predating this type declaration. */
    readonly clientHandle?: string;
    readonly displayName?: string;
    readonly status?: string;
    readonly errorMessage?: string;
    readonly warehouse?: string;
    readonly duration?: SearchTableTimeUnit;
    readonly targetLag?: number;
    readonly field?: SearchTableFieldWire;
    readonly attributeFields?: readonly SearchTableFieldWire[];
    readonly textIndexFields?: readonly SearchTableFieldWire[];
    readonly vectorIndexes?: readonly VectorIndexWire[];
    /** Legacy single-index embedding provider; paired with `field`. */
    readonly aiProviderConnector?: AiProviderConnectorRefWire;
    /** Linked-only: database holding the Cortex Search Service. */
    readonly linkedDatabase?: string;
    /** Linked-only: schema holding the Cortex Search Service. */
    readonly linkedSchema?: string;
    /** Linked-only: name of the existing Cortex Search Service. */
    readonly linkedServiceName?: string;
}
/**
 * Normalized deploy response for search tables. Extends `DeployResponse`
 * so the late-binding registry / stamp WeakMap can use `id` uniformly.
 * `searchTableId` is the same value as `id`; kept for symmetry with
 * `DeployedAgent.agentId` / `DeployedAutomation.automationId`.
 * `aspectId` is the owning aspect's id — preserved on the response so
 * a follow-up `getSearchTable`/`updateSearchTable` call (both of which
 * need `aspectId` in the `/v1/aspects/...` URL path) doesn't have to
 * thread the owner separately.
 */
export interface DeployedSearchTable extends DeployResponse {
    readonly searchTableId: string;
    readonly aspectId: string;
    readonly displayName?: string;
    readonly status?: string;
}
